mapper.select:
select a.finprod_id finprodId,
bok.ACCT_SUBJECT_TYPE finprodType, bok.ACCT_MODE profitType, bok.ACCT_MODE profitTypeCode, bok.BOOKSET_NAME finprodAbbr, DATE_FORMAT(a.val_date, '%Y-%m-%d') valDate, a.val_bal_flag valBalFlag, a.val_bal_flag valBalFlagCode, IFNULL(a.capital,0) capiTal,
CASE WHEN b.asset_value is not null THEN b.asset_value WHEN a.asset_value is not null THEN a.asset_value ELSE 0 END as assetValue, CASE WHEN b.net_unit_value is not null THEN b.net_unit_value WHEN a.net_unit_value is not null THEN a.net_unit_value ELSE 0 END as netUnitValue,
IFNULL(a.total_net_value,0) totalNetNalue, IFNULL(a.check_status,0) checkStatus, IFNULL(a.check_status,0) checkStatusCode, IFNULL(a.check_result,0) checkResult, IFNULL(a.check_result,0) checkResultCode, IFNULL(a.confirm_status,0) confirmStatus, IFNULL(a.confirm_status,0) confirmStatusCode, IFNULL(a.notice_status,0) noticeStatus, IFNULL(a.notice_status,0) noticeStatusCode, IFNULL(a.total_net_value,0) totalNetValue, IFNULL(a.TDY_YIELD ,0) tdyYield, IFNULL(seven_day_rate,0) sevenDayRate, IFNULL(pay_profit,0) payProfit,
IFNULL(bvtd.MARKET_VALUE,0) prdTotAssetVal, IFNULL(bvtd.MARKET_VALUE,0)-IFNULL(bvtd1.MARKET_VALUE,0) prdAssetVal
from BOK_VALBAL_TABLE_STATUS a
left join bok_bookset bok on a.finprod_id = bok.BOOKSET_ID
left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = a.finprod_id and bvtd.VAL_DATE = a.val_date and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = a.finprod_id and bvtd1.VAL_DATE = a.val_date and bvtd1.DETAIL_DIST = '06'
left join BOK_VALBAL_TABLE_STATUS_ADD b on a.finprod_id = b.finprod_id and a.val_date = b.val_date
where 1=1 and bok.ACCT_SUBJECT_TYPE != #{acctSubjectType}
and a.val_bal_flag='01'
AND a.finprod_Id in
#{finprodId}
AND IFNULL(a.check_Status,0) in
#{checkStatus}
AND IFNULL(a.notice_Status,0) in
#{noticeStatus}
AND IFNULL(a.confirm_Status,0) in
#{confirmStatus}
AND bok.ACCT_MODE in
#{profitType}
AND IFNULL(a.check_Result,0) in
#{checkResult}
AND a.val_Date >=STR_TO_DATE(#{valDateBegin},'%Y-%m-%d')
AND a.val_Date <=STR_TO_DATE(#{valDateEnd},'%Y-%m-%d')
AND a.finprod_Id = #{finprodIdForFlow}
AND a.val_Date = STR_TO_DATE(#{valDateForFlow},'%Y-%m-%d')
AND a.val_bal_flag = #{valBalFlagCodeForFlow}
order by a.val_Date desc

mapper.update:
      update BOK_VALBAL_TABLE_STATUS a
      set confirm_Status=#{confirmStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set NOTICE_STATUS=#{noticeStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}
